	"dataSources": {
		"ds_ap_by_location": {
			"name": "AP Count by Location",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| where (DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Access Points\") AND Site!=\"\" | eval Site=mvindex(split(Site,\"/\"),-1) | stats dc(DeviceID) as APs by Site | fillnull Site value=\"Unknown\" | rename Site as \"Location\""
			},
			"type": "ds.chain"
		},
		"ds_asset_base": {
			"name": "Asset Inventory Lookup Base",
			"options": {
				"query": "| inputlookup asset_inventory\n| fields device_type",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_base_devicehealth_ref": {
			"name": "IT - Critical Systems - ds_base_devicehealth",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n| stats latest(OverallHealth) as OverallHealth, latest(Reachability) as Reachability, latest(Manageability) as Manageability, latest(ReachabilityFailureReason) as ReachabilityFailureReason, latest(CPUUtilization) as CPUUtilization, latest(MemoryUtilization) as MemoryUtilization, latest(DeviceFamily) as DeviceFamily, latest(DeviceRole) as DeviceRole, latest(Platform) as Platform, latest(Site) as Site, latest(IpAddress) as IpAddress, latest(MACAddress) as MACAddress, latest(SerialNumber) as SerialNumber, latest(ImageVersion) as DeviceImgVersion, latest(Uptime) as UpTime, latest(UptimeSeconds) as UptimeSeconds by DeviceName, DeviceID\n| eval SoftwareVersion=DeviceImgVersion",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_base_issues_ref": {
			"name": "IT - Critical Systems - ds_base_issues",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\"\n| eval DeviceImgVersion=DeviceImageVersion\n| join type=left DeviceID [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | stats latest(Site) as SiteName, latest(Location) as SiteNameHierarchy by DeviceID ]\n| eval SiteName=coalesce(SiteName, \"Site enrichment unavailable\"), SiteNameHierarchy=coalesce(SiteNameHierarchy, SiteName), SiteType=null()\n| fields IssueID, IssueName, IssueCategory, IssueSpecificPriority, IssueStatus, IssueSpecificSeverity, IssueSpecificDescription, IssueSpecificSummary, IssueSpecificEntity, IssueSpecificEntityValue, IssueSpecificCategory, IssueSpecificName, IssueSpecificSource, IssueCount, IssueDeviceRole, DeviceName, DeviceFamily, DevicePlatform, DeviceRole, DeviceSerialNumber, DeviceSeries, DeviceIpAddress, DeviceImgVersion, DeviceMACAddress, SiteName, SiteNameHierarchy, SiteType, IssueClientMac, _time",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_base_topology_site_role": {
			"name": "Topology Site Role Base",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| eval role_order=case(DeviceRole==\"CORE\",1, DeviceRole==\"DISTRIBUTION\",2, DeviceRole==\"ACCESS\",3, DeviceRole==\"AP\",4, DeviceRole==\"WIRELESS_CONTROLLER\",2, DeviceRole==\"ROUTER\",1, 1==1,5), role_label=case(DeviceRole==\"ACCESS\",\"Access\", DeviceRole==\"DISTRIBUTION\",\"Distribution\", DeviceRole==\"CORE\",\"Core\", DeviceRole==\"WIRELESS_CONTROLLER\",\"WLC\", DeviceRole==\"AP\",\"AP\", DeviceRole==\"ROUTER\",\"Router\", isnotnull(DeviceRole),DeviceRole, 1==1,\"Unknown\") \n| eval site_short=mvindex(split(Site,\"/\"),-1) \n| where isnotnull(site_short) AND site_short!=\"\" \n| stats dc(DeviceName) as count by site_short, role_label, role_order \n| rename site_short as Site, role_label as Role"
			},
			"type": "ds.chain"
		},
		"ds_compliance": {
			"name": "Executive Dashboard - ds_compliance",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:compliance\" ComplianceStatus!=\"NOT_APPLICABLE\"\n| eval ok=if(ComplianceStatus==\"COMPLIANT\" OR ComplianceStatus==\"COMPLIANT_WARNING\",1,0)\n| stats sum(ok) as compliant, count as total\n| eval pct=if(total>0, round(compliant/total*100), 0)\n| fields pct",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_compliance_detail": {
			"name": "Building Resilience - ds_compliance_detail",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:compliance\" ComplianceStatus!=\"COMPLIANT\" ComplianceStatus!=\"NOT_APPLICABLE\"\n| stats latest(ComplianceStatus) as Status, latest(DeviceFamily) as Family, latest(IpAddress) as IP, latest(ImageVersion) as Version by DeviceName\n| rename DeviceName as device_name\n| lookup asset_inventory device_name OUTPUT location, management_source\n| rename device_name as Device, location as Location, management_source as Source\n| sort Status",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_compliance_donut": {
			"name": "IT - Critical Systems - ds_compliance_donut",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:compliance\" \n| stats latest(ComplianceStatus) as status by DeviceName \n| eval status=case(status==\"COMPLIANT\", \"Compliant\", status==\"COMPLIANT_WARNING\", \"Warning\", status==\"NON_COMPLIANT\", \"Non-Compliant\", status==\"NOT_APPLICABLE\", \"Not Applicable\", 1==1, status) \n| stats count by status",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_compliance_report": {
			"name": "IT - Critical Systems - ds_compliance_report",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:compliance\" ComplianceStatus=NON_COMPLIANT ComplianceDetail=True\n| stats dc(ComplianceComplianceType) as type_count, values(ComplianceComplianceType) as compliance_types, latest(IpAddress) as ip, latest(Platform) as platform, latest(DeviceSeries) as series, latest(DeviceFamily) as family, latest(DeviceRole) as role, latest(ImageVersion) as version, latest(Uptime) as uptime, latest(Manageability) as manageability, latest(Reachability) as reachability by DeviceName\n| eval compliance_types=mvjoin(compliance_types,\", \")\n| sort -type_count\n| rename DeviceName as \"Device Name\", ip as \"IP Address\", compliance_types as \"Compliance Types\", type_count as \"Type Count\", platform as Platform, series as \"Device Series\", family as \"Device Family\", role as \"Device Role\", version as \"Image Version\", uptime as Uptime, manageability as Manageability, reachability as Reachability",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_config_changes": {
			"name": "Executive Dashboard - ds_config_changes",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:audit:logs\" NOT name IN (\"REGISTER\",\"APIS_READY\",\"SERVICE_STARTUP\")\n| stats count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_config_detail": {
			"name": "IT Health - Recent Human Config Changes",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:audit:logs\" name=\"AUDIT_LOG\"\n userId!=\"system\" userId!=\"SYSTEM\" userId!=\"dnac-svc\" userId!=\"license-management\" userId!=\"localhost\" userId!=\"null\"\n NOT description=\"*read-only commands*\"\n NOT description=\"*preview*\"\n NOT description=\"Service request processing completed*\"\n NOT description=\"Going to deploy*\"\n| where (parentInstanceId=\"null\" OR parentInstanceId=\"\" OR isnull(parentInstanceId))\n| where NOT (description LIKE \"Executing command%display%\")\n| rex field=description mode=sed \"s/[\\r\\n\\t]+/ /g\"\n| rex field=description mode=sed \"s/ +/ /g\"\n| eval description = replace(description, \"&quot;\", \"\\\"\")\n| eval description = replace(description, \"&amp;\", \"&\")\n| eval description = replace(description, \"&lt;\", \"<\")\n| eval description = replace(description, \"&gt;\", \">\")\n| eval admin = coalesce(adminName, userId, \"unknown\")\n| spath path=\"additionalDetails.eventMetadata.auditLogMetadata.type\" output=audit_type\n| spath path=\"network.deviceId\" output=net_deviceId\n| eval net_deviceId = if(net_deviceId IN (\"null\",\"SYSTEM\",\"\") OR isnull(net_deviceId), null(), net_deviceId)\n| rex field=description \"Network Profile \\[.*?\\\"name\\\":\\\"(?<x_profile>[^\\\"]+)\"\n| rex field=description \"Creating task schedule.*?description:\\s*'(?<x_task>[^']+)'\"\n| rex field=description \"AP Provisioning request for AP\\(s\\) in (?<x_ap_site>[^,]+),\"\n| rex field=description \"for activity '(?<x_activity>[^']+)'\"\n| rex field=description \"network device (?<x_ip>\\d+\\.\\d+\\.\\d+\\.\\d+)\"\n| rex field=description \"deployed template (?<x_template>\\S+?)\\.?$\"\n| eval target = coalesce(net_deviceId, x_profile, x_task, x_ap_site, x_activity, x_ip, x_template, \"-\")\n| eval how = case(\n audit_type=\"CLI\", \"DNAC CLI session\",\n audit_type=\"API\", \"DNAC UI / REST API\",\n audit_type=\"NETCONF\", \"DNAC NETCONF push\",\n audit_type=\"SOCKET\", \"DNAC internal\",\n 1=1, \"DNAC \" . coalesce(audit_type, \"audit\"))\n| eval description = if(len(description) > 200, substr(description, 1, 197) . \"...\", description)\n| table _time admin how description target\n| rename admin as \"Who\", how as \"How\", description as \"What\", target as \"Target\"\n| sort - _time\n| head 5000",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_config_trend": {
			"name": "IT Health - Config Change Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:audit:logs\" name=\"AUDIT_LOG\"\n userId!=\"system\" userId!=\"SYSTEM\" userId!=\"dnac-svc\" userId!=\"license-management\" userId!=\"localhost\" userId!=\"null\"\n NOT description=\"*read-only commands*\"\n NOT description=\"*preview*\"\n NOT description=\"Service request processing completed*\"\n NOT description=\"Going to deploy*\"\n| where (parentInstanceId=\"null\" OR parentInstanceId=\"\" OR isnull(parentInstanceId))\n| where NOT (description LIKE \"Executing command%display%\")\n| eval admin=coalesce(adminName, userId, \"unknown\")\n| bin span=15m _time as bucket\n| eval session = admin . \"|\" . bucket\n| timechart span=15m fixedrange=false dc(session) as workflows by admin",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cpu_mem": {
			"name": "CPU/Memory Alerts Base",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| where CPUUtilization > 80 OR MemoryUtilization > 80 | eval cpu_status=if(CPUUtilization>90,\"Critical\",if(CPUUtilization>80,\"Warning\",\"OK\")), mem_status=if(MemoryUtilization>90,\"Critical\",if(MemoryUtilization>80,\"Warning\",\"OK\")) | table DeviceName, DeviceFamily, Platform, Site, CPUUtilization, cpu_status, MemoryUtilization, mem_status | sort -CPUUtilization | fillnull value=\"—\""
			},
			"type": "ds.chain"
		},
		"ds_cpu_mem_trend": {
			"name": "CPU/Memory Alerts Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | where CPUUtilization > 80 OR MemoryUtilization > 80 | timechart fixedrange=false dc(DeviceName) as \"CPU/Memory Alerts\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dev_health_trend": {
			"name": "Shared - ds_dev_health_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | where OverallHealth>=0 | eval health=OverallHealth*10 | timechart fixedrange=false avg(health) as score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_device_health": {
			"name": "IT Health - Device Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" | eval OverallHealth=tonumber(mvindex(OverallHealth, 0)) | where OverallHealth>=0 | timechart fixedrange=false avg(eval(round(OverallHealth * 10, 2))) as health",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_device_inventory": {
			"name": "Device Inventory by Type",
			"options": {
				"extend": "ds_asset_base",
				"query": "| stats count by device_type | rename device_type as category"
			},
			"type": "ds.chain"
		},
		"ds_dhcp_events": {
			"name": "IT - Critical Systems - ds_dhcp_pool_exhaustion",
			"options": {
				"query": "`index_dhcp` sourcetype=\"DhcpSrvLog\"\n| rex \"^(?<event_id>\\d+),(?<date>[^,]+),(?<time>[^,]+),(?<description>[^,]*),(?<ip_address>[^,]+),(?<hostname>[^,]*),(?<mac_address>[^,]*)\"\n| eval event_type=case(event_id==\"13\",\"IP In Use\", event_id==\"14\",\"Lease Denied\", event_id==\"15\",\"Range Exhausted\", event_id==\"16\",\"Range Extended\", 1==1,\"Event \".event_id)\n| where event_id IN (\"13\",\"14\",\"15\",\"16\")\n| stats dc(ip_address) as unique_ips, dc(mac_address) as unique_clients, count as events, earliest(_time) as first_seen, latest(_time) as last_seen by event_type\n| eval first_seen=strftime(first_seen, \"%Y-%m-%d %H:%M\"), last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M\")\n| sort -events\n| rename event_type as \"Event\", unique_ips as \"Unique IPs\", unique_clients as \"Unique Clients\", events as \"Events\", first_seen as \"First Seen\", last_seen as \"Last Seen\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_dhcp_trend": {
			"name": "DHCP Pool Events Trend",
			"options": {
				"query": "`index_dhcp` sourcetype=\"DhcpSrvLog\" | rex \"^(?<event_id>\\d+),\" | where event_id IN (\"13\",\"14\",\"15\",\"16\",\"17\",\"20\",\"21\",\"36\") | timechart fixedrange=false count as \"DHCP Pool Events\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_health_dist": {
			"name": "Health Score Distribution",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| eval health_band=case(OverallHealth>=8,\"Good (8-10)\",OverallHealth>=5,\"Fair (5-7)\",OverallHealth>=1,\"Poor (1-4)\",1==1,\"No Score\") | stats count by DeviceFamily, health_band | fillnull health_band value=\"No Score\""
			},
			"type": "ds.chain"
		},
		"ds_intf_util": {
			"name": "Interface Utilization Alerts",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| where match(IssueName,\"(?i)(high input|high output|interface utilization)\") | stats count as issue_count, values(IssueSpecificEntity) as affected_interfaces, latest(IssueSpecificSeverity) as severity by DeviceName, SiteName | sort -issue_count | fillnull value=\"—\""
			},
			"type": "ds.chain"
		},
		"ds_inv_total": {
			"name": "Device Inventory",
			"options": {
				"extend": "ds_device_inventory",
				"query": "| stats sum(count) as total | fields total"
			},
			"type": "ds.chain"
		},
		"ds_ise_device_logins": {
			"name": "IT Health - Identity-attested device logins",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\"\n| rex field=_raw \"(?<event_class>CISE_(?:Passed_Authentications|Failed_Attempts|Administrative_and_Operational|Posture|Profiler|RADIUS_Accounting))\"\n| where (event_class=\"CISE_Administrative_and_Operational\" OR (event_class=\"CISE_Passed_Authentications\" AND match(_raw, \"TACACS|Device-Admin\")) OR (event_class=\"CISE_Failed_Attempts\" AND match(_raw, \"TACACS|Device-Admin\")))\n| rex field=_raw \"(?:UserName|User-Name|User=)\\s*[=:]?\\s*(?<ise_user>[^,;\\s\\\"]+)\"\n| rex field=_raw \"(?:Device IP Address|NAS-IP-Address|NAS_IP_Address)\\s*=\\s*(?<target_device>[\\d.]+)\"\n| eval ise_action=case(\n match(_raw, \"Command Authorization succeeded\"), \"TACACS+ command allowed\",\n match(_raw, \"Command Authorization failed\"), \"TACACS+ command DENIED\",\n match(_raw, \"Authentication succeeded\"), \"Device login succeeded\",\n match(_raw, \"Authentication failed\"), \"Device login FAILED\",\n event_class=\"CISE_Passed_Authentications\", \"Auth succeeded\",\n event_class=\"CISE_Failed_Attempts\", \"Auth FAILED\",\n event_class=\"CISE_Administrative_and_Operational\", \"ISE admin operation\",\n 1=1, event_class)\n| where isnotnull(ise_user) AND ise_user!=\"\" AND NOT match(ise_user, \"^([0-9A-Fa-f]{2}[:.]){2,}\")\n| stats count, values(ise_action) as actions, latest(target_device) as last_device, latest(_time) as last_seen by ise_user\n| eval actions=mvjoin(actions, \", \")\n| eval last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M\")\n| rename ise_user as \"Who (AD/ISE user)\", count as \"Events\", actions as \"ISE actions seen\", last_device as \"Last device\", last_seen as \"Last seen\"\n| sort -Events",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_issue_by_priority": {
			"name": "Issues by Priority",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| stats count by IssueSpecificPriority"
			},
			"type": "ds.chain"
		},
		"ds_issue_by_severity": {
			"name": "Issues by Severity",
			"options": {
				"extend": "ds_open_issues",
				"query": "| eval P1=p1, P2=p2, P3=p3, P4=p4 | fields P1 P2 P3 P4 | transpose 0 column_name=severity header_field=severity | rename \"row 1\" as count"
			},
			"type": "ds.chain"
		},
		"ds_issue_by_site": {
			"name": "Issues by Site",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| stats count as total_issues, count(eval(IssueSpecificSeverity==\"HIGH\" OR IssueSpecificPriority==\"P1\")) as critical_high by SiteName | sort -total_issues | head 10 | fillnull SiteName value=\"Unknown\" | rename SiteName as Site"
			},
			"type": "ds.chain"
		},
		"ds_issue_category_split": {
			"name": "Network vs Client Issues",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| eval category=case(IssueSpecificCategory==\"Connected\",\"Client\",IssueSpecificCategory IN (\"Availability\",\"Connectivity\",\"Device\",\"Utilization\"),\"Network\",1==1,\"Other\") | stats dc(IssueID) as count by category"
			},
			"type": "ds.chain"
		},
		"ds_issue_trend": {
			"name": "Issue Trend",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| timechart dc(IssueID) as issues"
			},
			"type": "ds.chain"
		},
		"ds_issue_trend_cat": {
			"name": "IT - Critical Systems - ds_issue_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\"\n| eval issue_group=case(match(IssueName,\"High input\"),\"Interface Utilization\", match(IssueName,\"BGP\"),\"BGP Instability\", match(IssueName,\"AP\"),\"AP Issues\", match(IssueName,\"AAA\"),\"AAA/RADIUS\", match(IssueName,\"Host flap\"),\"MAC Flapping\", match(IssueName,\"Network Device\"),\"Device Reachability\", match(IssueName,\"Internet\"),\"Internet Connectivity\", match(IssueName,\"5 GHz\"),\"Wireless Radio\", match(IssueName,\"This Device\"),\"Device Health\", 1==1,IssueSpecificCategory)\n| timechart dc(IssueID) by issue_group limit=10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_issues_trend": {
			"name": "Open Issues Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" | timechart fixedrange=false dc(IssueID) as issues",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_cpu_mem": {
			"name": "KPI CPU/Memory Alerts",
			"options": {
				"extend": "ds_cpu_mem_trend",
				"query": "| fields _time \"CPU/Memory Alerts\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_dev_health": {
			"name": "KPI Device Health",
			"options": {
				"extend": "ds_dev_health_trend",
				"query": "| fields _time score"
			},
			"type": "ds.chain"
		},
		"ds_kpi_dhcp": {
			"name": "KPI DHCP Pool Events",
			"options": {
				"extend": "ds_dhcp_trend",
				"query": "| fields _time \"DHCP Pool Events\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_issues": {
			"name": "KPI Open Issues",
			"options": {
				"extend": "ds_issues_trend",
				"query": "| fields _time issues"
			},
			"type": "ds.chain"
		},
		"ds_kpi_net_health": {
			"name": "KPI Network Health",
			"options": {
				"extend": "ds_net_health_trend",
				"query": "| fields _time score"
			},
			"type": "ds.chain"
		},
		"ds_kpi_reboots": {
			"name": "KPI Recent Reboots",
			"options": {
				"extend": "ds_reboots_trend",
				"query": "| fields _time \"Recent Reboots\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_syslog": {
			"name": "KPI Syslog Critical",
			"options": {
				"extend": "ds_syslog_trend",
				"query": "| fields _time count"
			},
			"type": "ds.chain"
		},
		"ds_kpi_unreachable": {
			"name": "KPI Unreachable Devices",
			"options": {
				"extend": "ds_unreachable_trend",
				"query": "| fields _time \"Unreachable Devices\""
			},
			"type": "ds.chain"
		},
		"ds_link_flap_storm": {
			"name": "IT - Critical Systems - ds_link_flap_storm",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" (\"%LINEPROTO-5-UPDOWN\" OR \"%LINK-3-UPDOWN\" OR \"%LINK-5-CHANGED\")\n| rex \"Interface (?<interface>\\S+)\"\n| stats count as flap_count, dc(interface) as intf_count, earliest(_time) as first_flap, latest(_time) as last_flap by host\n| eval duration_sec=round(last_flap-first_flap,0), first_flap=strftime(first_flap,\"%H:%M:%S\"), last_flap=strftime(last_flap,\"%H:%M:%S\"), flaps_per_min=if(duration_sec>0,round(flap_count/(duration_sec/60),1),flap_count), event_type=if(intf_count>5 AND duration_sec<120,\"Power Event (mass flap)\",\"Isolated Flap\")\n| sort -flap_count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_link_graph": {
			"name": "Live Network Topology",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| eval site_short=mvindex(split(Site,\"/\"),-1), role_label=case(DeviceRole==\"ACCESS\",\"Access\", DeviceRole==\"DISTRIBUTION\",\"Distribution\", DeviceRole==\"CORE\",\"Core\", DeviceRole==\"WIRELESS_CONTROLLER\",\"WLC\", DeviceRole==\"AP\",\"AP\", DeviceRole==\"ROUTER\",\"Router\", DeviceRole==\"BORDER ROUTER\",\"Border Router\", isnotnull(DeviceRole),DeviceRole, 1==1,\"Unknown\") | stats dc(DeviceName) as count by site_short, role_label | eval Site=site_short, Role=role_label.\" (\".count.\")\" | table Site, Role"
			},
			"type": "ds.chain"
		},
		"ds_net_health_trend": {
			"name": "Network Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:networkhealth\" category=\"All\" | timechart fixedrange=false latest(healthScore) as score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_network_health": {
			"name": "IT Health - Network Health Score",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:networkhealth\" category=\"All\" | timechart fixedrange=false latest(healthScore) as health",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_open_issues": {
			"name": "Open Issues Base",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| stats latest(*) as * by IssueID \n| stats count as issues, count(eval(IssueSpecificPriority==\"P1\")) as p1, count(eval(IssueSpecificPriority==\"P2\")) as p2, count(eval(IssueSpecificPriority==\"P3\")) as p3, count(eval(IssueSpecificPriority==\"P4\")) as p4 \n| fields issues p1 p2 p3 p4"
			},
			"type": "ds.chain"
		},
		"ds_power_detection": {
			"name": "IT - Critical Systems - ds_power_event_detection",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" (\"%SYS-5-RELOAD\" OR \"%SYS-5-RESTART\" OR \"%SYS-5-CONFIG_I\" OR \"%PLATFORM_ENV-1-FAN\" OR \"%PLATFORM_ENV-6-BOARD\" OR \"%REDUNDANCY-5-SWITCHOVER\" OR \"%STACKMGR-6-STACK_LINK_CHANGE\" OR \"%SYS-6-LOGGINGHOST_STARTSTOP\" OR \"%SYS-2-MALLOCFAIL\" OR \"%PLATFORM-2-PEM_NOINPUT\")\n| eval event_class=case(match(_raw,\"RELOAD|RESTART\"),\"Reload/Restart\", match(_raw,\"PLATFORM_ENV|PEM_NOINPUT\"),\"Power/Environment\", match(_raw,\"REDUNDANCY|SWITCHOVER\"),\"Supervisor Switchover\", match(_raw,\"STACKMGR\"),\"Stack Change\", match(_raw,\"MALLOCFAIL\"),\"Memory Failure\", match(_raw,\"CONFIG_I\"),\"Post-Boot Config\", match(_raw,\"LOGGINGHOST\"),\"Logging Restart\", 1==1,\"Other\")\n| stats count as events, dc(host) as affected_devices, values(host) as devices, earliest(_time) as first_event, latest(_time) as last_event by event_class\n| eval duration_sec=last_event-first_event, first_event=strftime(first_event,\"%H:%M:%S\"), last_event=strftime(last_event,\"%H:%M:%S\"), devices=mvjoin(devices,\", \")\n| sort -events",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_power_summary": {
			"name": "IT - Critical Systems - ds_power_event_summary",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" (\"%SYS-5-RELOAD\" OR \"%SYS-5-RESTART\" OR \"%PLATFORM_ENV\" OR \"%REDUNDANCY-5-SWITCHOVER\" OR \"%STACKMGR\" OR \"%SYS-2-MALLOCFAIL\" OR \"%PLATFORM-2-PEM_NOINPUT\")\n| stats count as power_events, dc(host) as affected_devices, earliest(_time) as first_event, latest(_time) as last_event \n| eval time_span_min=round((last_event-first_event)/60,1), first_event=strftime(first_event,\"%Y-%m-%d %H:%M:%S\"), last_event=strftime(last_event,\"%Y-%m-%d %H:%M:%S\") \n| fillnull value=0 power_events, affected_devices",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_power_summary_count": {
			"name": "Power Events",
			"options": {
				"extend": "ds_power_summary",
				"query": "| eval count=power_events | fields count"
			},
			"type": "ds.chain"
		},
		"ds_power_timeline": {
			"name": "IT Health - Power Event Timeline",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" (\"%SYS-5-RELOAD\" OR \"%SYS-5-RESTART\" OR \"%LINEPROTO-5-UPDOWN\" OR \"%LINK-3-UPDOWN\" OR \"%LINK-5-CHANGED\" OR \"%OSPF-5-ADJCHG\" OR \"%EIGRP-5-NBRCHANGE\" OR \"%BGP-5-ADJCHANGE\" OR \"%STP-6-TOPOLOGY\" OR \"%REDUNDANCY-5-SWITCHOVER\" OR \"%STACKMGR\" OR \"%PLATFORM_ENV\" OR \"%SYS-6-LOGGINGHOST\") | eval event_class=case(match(_raw,\"RELOAD|RESTART\"),\"1-Reload\", match(_raw,\"PLATFORM_ENV|PEM\"),\"1-Power/Env\", match(_raw,\"LINK-3-UPDOWN|LINK-5-CHANGED\"),\"2-Link Down/Up\", match(_raw,\"LINEPROTO-5-UPDOWN\"),\"3-Protocol Down/Up\", match(_raw,\"OSPF|EIGRP|BGP\"),\"4-Routing Reconvergence\", match(_raw,\"STP-6-TOPOLOGY\"),\"5-STP Reconvergence\", match(_raw,\"REDUNDANCY|STACKMGR\"),\"2-HA/Stack Change\", match(_raw,\"LOGGINGHOST\"),\"6-Recovery\", 1==1,\"7-Other\") | timechart fixedrange=false count by event_class",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_reboots": {
			"name": "Recent Reboots Base",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| where UptimeSeconds<14400 \n| table DeviceName, DeviceFamily, Platform, Site, IpAddress, UpTime, DeviceImgVersion \n| sort UptimeSeconds \n| rename DeviceFamily as \"Device Family\", IpAddress as \"IP Address\", DeviceImgVersion as \"Software\" \n| fillnull value=\"—\""
			},
			"type": "ds.chain"
		},
		"ds_reboots_trend": {
			"name": "Recent Reboots Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" UptimeSeconds<14400 | timechart fixedrange=false dc(DeviceName) as \"Recent Reboots\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_routing_reconvergence": {
			"name": "IT - Critical Systems - ds_routing_reconvergence",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" (\"%OSPF-5-ADJCHG\" OR \"%EIGRP-5-NBRCHANGE\" OR \"%BGP-5-ADJCHANGE\" OR \"%BGP-3-NOTIFICATION\")\n| eval protocol=case(match(_raw,\"OSPF\"),\"OSPF\", match(_raw,\"EIGRP\"),\"EIGRP\", match(_raw,\"BGP\"),\"BGP\"), state=if(match(_raw,\"(?i)up|FULL|established|adjacency\"),\"Up\",\"Down\")\n| stats count as events, count(eval(state==\"Down\")) as down_events, count(eval(state==\"Up\")) as up_events, earliest(_time) as first_event, latest(_time) as last_event by host, protocol\n| eval recovery_sec=round(last_event-first_event,0), first_event=strftime(first_event,\"%H:%M:%S\"), last_event=strftime(last_event,\"%H:%M:%S\")\n| sort -events",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_site_health": {
			"name": "IT - Critical Systems - ds_site_health",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" earliest=-15m\n| eval Site=`dnac_site_normalize(coalesce(Site, Location))`\n| where Site!=\"\"\n| stats avg(eval(if(OverallHealth>=0, OverallHealth, null))) as healthRaw, count(eval(OverallHealth>=8)) as good, count(eval(OverallHealth>=4 AND OverallHealth<8)) as fair, count(eval(OverallHealth<4 AND OverallHealth>=0)) as bad, dc(DeviceID) as total by Site\n| eval health=round(healthRaw*10)\n| fields Site health good bad fair total\n| sort -health",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_site_health_distribution": {
			"name": "Site Health Distribution",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| eval site_short=mvindex(split(Site,\"/\"),-1) | where isnotnull(site_short) AND site_short!=\"\" | eval health_status=case(isnull(OverallHealth) OR OverallHealth==0,\"Unknown\", OverallHealth>=8,\"Healthy\", OverallHealth>=4,\"Warning\", 1==1,\"Critical\") | chart dc(DeviceID) over site_short by health_status | fillnull value=0 | eval _Healthy=coalesce(Healthy,0), _Warning=coalesce(Warning,0), _Critical=coalesce(Critical,0), _Unknown=coalesce(Unknown,0), _Total=_Healthy+_Warning+_Critical+_Unknown | where _Total>0 | sort 12 -_Total | rename site_short as Site | table Site _Healthy _Warning _Critical _Unknown | rename _Healthy as Healthy, _Warning as Warning, _Critical as Critical, _Unknown as Unknown"
			},
			"type": "ds.chain"
		},
		"ds_stp_reconvergence": {
			"name": "IT - Critical Systems - ds_stp_reconvergence",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" (\"%STP-6-TOPOLOGY\" OR \"%SPANTREE-2-ROOTCHANGE\" OR \"%SPANTREE-6-ROOTCHANGE\" OR \"%SPANTREE-2-BLOCK_BPDUGUARD\")\n| rex \"VLAN(?<vlan_id>\\d+)\"\n| stats count as topology_changes, dc(vlan_id) as vlans_affected, earliest(_time) as first_event, latest(_time) as last_event by host\n| eval duration_sec=round(last_event-first_event,0), first_event=strftime(first_event,\"%H:%M:%S\"), last_event=strftime(last_event,\"%H:%M:%S\")\n| sort -topology_changes",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_switch_by_location": {
			"name": "Switch Count by Location",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| where DeviceFamily=\"Switches and Hubs\" AND Site!=\"\" | eval Site=mvindex(split(Site,\"/\"),-1) | stats dc(DeviceID) as Switches by Site"
			},
			"type": "ds.chain"
		},
		"ds_syslog_severity": {
			"name": "IT - Critical Systems - ds_syslog_severity",
			"options": {
				"query": "`index_network` (sourcetype=\"cisco:ios\")\n| rex \"%(?<facility>[A-Z_]+)-(?<severity_id>\\d+)-(?<mnemonic>[A-Z_]+)\"\n| eval severity=case(severity_id<=2,\"Critical\", severity_id==3,\"Error\", severity_id<=5,\"Warning\", 1==1,\"Info\")\n| stats count as events, dc(host) as hosts, dc(mnemonic) as message_types by severity",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_syslog_trend": {
			"name": "Syslog Critical Trend",
			"options": {
				"query": "`index_network` sourcetype=\"cisco:ios\" | rex \"%(?<facility>[A-Z_]+)-(?<severity_id>\\d+)-(?<mnemonic>[A-Z_]+)\" | where severity_id<=2 | timechart fixedrange=false count as count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_alerts_summary": {
			"name": "IT Health - ThousandEyes Alerts Summary by Severity",
			"options": {
				"query": "| tstats `scd_summariesonly` count\nFROM datamodel=\"Cisco_ThousandEyes.Alerts\"\nBY Alerts.severity\n| rename Alerts.severity AS Severity\n| sort - count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_alerts_table": {
			"name": "IT Health - ThousandEyes Active Alerts Recent 20",
			"options": {
				"query": "| tstats `scd_summariesonly` count, values(Alerts.triggerTime) as triggerTime, values(Alerts.accountId) as accountId, values(Alerts.organizationId) as organizationId, values(Alerts.testId) as testId, values(Alerts.testName) as testName, values(Alerts.testType) as testType, values(Alerts.permalink) as permalink, values(Alerts.expression) as expression, values(Alerts.severity) as severity\n    FROM datamodel=\"Cisco_ThousandEyes.Alerts\"\n    BY _time, Alerts.alertId \n| eval \"Trigger Time\"=coalesce(strftime(triggerTime, \"%Y-%m-%d %H:%M:%S\"), strftime(_time, \"%Y-%m-%d %H:%M:%S\")) \n| rename accountId AS \"Account ID\", organizationId AS \"Org ID\", testId AS \"Test ID\", testName AS \"Test Name\", testType AS \"Test Type\", permalink AS \"Permalink\", expression AS \"Expression\", severity AS \"Severity\", Alerts.alertId AS \"Alert ID\" \n| sort 0 - \"Trigger Time\" \n| fields - _time, triggerTime, count \n| head 20 \n| table \"Trigger Time\", \"Account ID\", \"Org ID\", \"Test ID\", \"Test Name\", \"Test Type\", \"Expression\", \"Severity\", \"Alert ID\", \"Permalink\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_alerts_timeline": {
			"name": "IT Health - ThousandEyes Alerts Timeline",
			"options": {
				"query": "| tstats `scd_summariesonly` count\nFROM datamodel=\"Cisco_ThousandEyes.Alerts\"\nBY Alerts.severity, _time span=1h\n| rename Alerts.severity AS Severity\n| timechart span=1h sum(count) AS count BY Severity",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_endpoint_traces": {
			"name": "IT Health - ThousandEyes Endpoint Metric Health",
			"options": {
				"query": "`index_thousandeyes` sourcetype=\"cisco:thousandeyes:metric\" (\"thousandeyes.test.type\"=\"http-server\" OR \"thousandeyes.test.type\"=\"page-load\" OR \"thousandeyes.test.type\"=\"api\" OR \"thousandeyes.test.type\"=\"web-transaction\" OR \"thousandeyes.test.type\"=\"agent-to-server\")\n| eval endpoint=coalesce('server.address', 'url.domain', 'thousandeyes.test.domain', 'http.url', 'thousandeyes.test.name', \"Unknown endpoint\")\n| eval agent_name=coalesce('thousandeyes.source.agent.name', 'source.agent.name', \"Unknown agent\")\n| eval test_name=coalesce('thousandeyes.test.name', \"Unknown test\")\n| eval test_type=coalesce('thousandeyes.test.type', \"Unknown type\")\n| eval test_id=coalesce('thousandeyes.test.id', 'test.id', test_id, testId, tid, \"\")\n| eval account_id=coalesce('thousandeyes.account.id', account_id, aid)\n| eval permalink=coalesce('thousandeyes.permalink', permalink)\n| eval permalink=if(isnotnull(permalink) AND match(permalink,\"^https?://\") AND NOT match(permalink,\"(?i)app\\.example\\.com|account=9999999|test=demo\"), permalink, null())\n| stats latest(metric_name:http.server.request.availability) as http_availability_pct latest(metric_name:web.page.load.completion) as page_completion_pct latest(metric_name:network.latency) as latency_s latest(metric_name:network.loss) as loss_pct latest(metric_name:network.jitter) as jitter_ms latest(metric_name:http.client.request.duration) as http_duration latest(metric_name:web.page.load.duration) as page_load_duration latest(permalink) as permalink max(_time) as last_seen by endpoint agent_name test_name test_type account_id test_id\n| where endpoint!=\"Unknown endpoint\" OR agent_name!=\"Unknown agent\" OR test_name!=\"Unknown test\"\n| eval availability_pct=round(coalesce(http_availability_pct, page_completion_pct), 2)\n| eval latency_ms=if(isnotnull(latency_s), round(latency_s*1000, 1), null())\n| eval loss_pct=if(isnotnull(loss_pct), round(loss_pct, 2), null())\n| eval jitter_ms=if(isnotnull(jitter_ms), round(jitter_ms, 1), null())\n| eval http_duration=if(isnotnull(http_duration), round(http_duration, 1), null())\n| eval page_load_duration=if(isnotnull(page_load_duration), round(page_load_duration, 1), null())\n| eval status=case((isnotnull(availability_pct) AND availability_pct<95) OR loss_pct>=5 OR latency_ms>=200, \"Critical\", (isnotnull(availability_pct) AND availability_pct<99) OR loss_pct>=1 OR latency_ms>=100 OR jitter_ms>=30, \"Degraded\", 1==1, \"Healthy\")\n| eval status_rank=case(status=\"Critical\", 1, status=\"Degraded\", 2, status=\"Healthy\", 3, 1==1, 4)\n| eval \"Last Seen\"=strftime(last_seen, \"%Y-%m-%d %H:%M:%S %Z\")\n| eval generated_permalink=case(test_id!=\"\" AND lower(test_id)!=\"demo\" AND isnotnull(account_id) AND account_id!=\"\" AND account_id!=\"9999999\", \"https://app.thousandeyes.com/network-app-synthetics/views/?__a=\".account_id.\"&testId=\".test_id, test_id!=\"\" AND lower(test_id)!=\"demo\", \"https://app.thousandeyes.com/network-app-synthetics/views/?testId=\".test_id)\n| eval permalink=coalesce(permalink, generated_permalink)\n| sort 0 status_rank availability_pct -latency_ms -loss_pct -jitter_ms\n| rename endpoint as \"Endpoint\", agent_name as \"Agent\", test_name as \"Test Name\", test_type as \"Test Type\", status as \"Status\", availability_pct as \"Availability %\", latency_ms as \"Latency (ms)\", loss_pct as \"Loss %\", jitter_ms as \"Jitter (ms)\", http_duration as \"HTTP Duration\", page_load_duration as \"Page Load Duration\", account_id as \"Account ID\", permalink as \"TE Link\"\n| table \"Status\", \"Endpoint\", \"Agent\", \"Test Name\", \"Test Type\", \"Last Seen\", \"Availability %\", \"Latency (ms)\", \"Loss %\", \"Jitter (ms)\", \"HTTP Duration\", \"Page Load Duration\", \"Account ID\", \"TE Link\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_network_jitter": {
			"name": "IT Health - ThousandEyes Network Jitter",
			"options": {
				"query": "| tstats `scd_summariesonly` avg(Test_Metrics.metric_name:network.jitter) as avg_jitter\nFROM datamodel=\"Cisco_ThousandEyes.Test_Metrics\"\nWHERE Test_Metrics.metric_name:network.jitter=\"*\"\nTest_Metrics.thousandeyes.test.type IN (\"agent-to-server\",\"agent-to-agent\")\nBY _time, Test_Metrics.server.address\n| timechart eval(round(avg(avg_jitter), 2)) as avg_jitter BY Test_Metrics.server.address\n| sort 0 - avg_jitter",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_network_latency": {
			"name": "IT Health - ThousandEyes Network Latency",
			"options": {
				"query": "| tstats `scd_summariesonly` avg(Test_Metrics.metric_name:network.latency) as avg_latency\nFROM datamodel=\"Cisco_ThousandEyes.Test_Metrics\"\nWHERE Test_Metrics.metric_name:network.latency=\"*\"\nTest_Metrics.thousandeyes.test.type IN (\"agent-to-server\",\"agent-to-agent\")\nBY _time, Test_Metrics.server.address\n| timechart eval(round(avg(avg_latency), 2)) as avg_latency BY Test_Metrics.server.address\n| sort 0 - avg_latency",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_te_network_loss": {
			"name": "IT Health - ThousandEyes Network Loss",
			"options": {
				"query": "| tstats `scd_summariesonly` avg(Test_Metrics.metric_name:network.loss) as avg_loss\nFROM datamodel=\"Cisco_ThousandEyes.Test_Metrics\"\nWHERE Test_Metrics.metric_name:network.loss=\"*\"\nTest_Metrics.thousandeyes.test.type IN (\"agent-to-server\",\"agent-to-agent\")\nBY _time, Test_Metrics.server.address\n| timechart eval(round(avg(avg_loss), 2)) as avg_loss BY Test_Metrics.server.address\n| sort 0 - avg_loss",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_top_client_issues": {
			"name": "Top Client Issues",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| where IssueSpecificCategory==\"Connected\" | stats dc(IssueID) as Count by IssueName | sort -Count | head 5 | rename IssueName as Issue"
			},
			"type": "ds.chain"
		},
		"ds_top_issue_devices": {
			"name": "IT - Critical Systems - ds_top_issue_devices",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n| stats latest(IssueCount) as issue_count, latest(OverallHealth) as health, latest(CPUUtilization) as cpu, latest(MemoryUtilization) as memory, latest(DeviceFamily) as family, latest(Platform) as platform, latest(Site) as site, latest(IpAddress) as ip by DeviceName\n| where issue_count>0 OR health<5 OR cpu>80 OR memory>80\n| eval concern=case(issue_count>5, \"High Issues (\".issue_count.\")\", health<5, \"Low Health (\".health.\")\", cpu>80, \"High CPU (\".cpu.\"%)\", memory>80, \"High Memory (\".memory.\"%)\", issue_count>0, \"Issues (\".issue_count.\")\", 1==1, \"Monitor\")\n| sort -issue_count, health, -cpu\n| rename DeviceName as Device",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_top_network_issues": {
			"name": "Top Network Issues",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| where IssueSpecificCategory IN (\"Availability\",\"Connectivity\",\"Device\",\"Utilization\") | stats dc(IssueID) as Count by IssueName | sort -Count | head 5 | rename IssueName as Issue"
			},
			"type": "ds.chain"
		},
		"ds_top_sites_issues": {
			"name": "Top Sites by Issue Count",
			"options": {
				"extend": "ds_base_issues_ref",
				"query": "| stats dc(IssueID) as count by SiteName | sort -count | head 5 | rename SiteName as site"
			},
			"type": "ds.chain"
		},
		"ds_topology_by_role": {
			"name": "Devices by Role",
			"options": {
				"extend": "ds_base_topology_site_role",
				"query": "| stats sum(count) as devices by Role"
			},
			"type": "ds.chain"
		},
		"ds_topology_device_table": {
			"name": "Live Device Inventory",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| table DeviceName, DeviceFamily, DeviceRole, Platform, Site, IpAddress, MACAddress, SerialNumber, OverallHealth, Reachability | fillnull value=\"—\" | sort Site, DeviceRole, DeviceName"
			},
			"type": "ds.chain"
		},
		"ds_unreachable": {
			"name": "Unreachable Devices Base",
			"options": {
				"extend": "ds_base_devicehealth_ref",
				"query": "| where Reachability=\"Unreachable\" | rename ReachabilityFailureReason as Reason, OverallHealth as Health, DeviceFamily as Family | table DeviceName, Family, Platform, Site, IpAddress, Reason, Health | fillnull value=\"—\""
			},
			"type": "ds.chain"
		},
		"ds_unreachable_trend": {
			"name": "Unreachable Devices Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" Reachability=\"Unreachable\" | timechart fixedrange=false dc(DeviceName) as \"Unreachable Devices\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_uxh_base_client_ref": {
			"name": "IT Health - User Experience - ds_uxh_base_client_ref",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| fields macAddress, osType, deviceType",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_uxh_client_trend": {
			"name": "IT Health - User Experience - ds_uxh_client_trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRED\" OR clientType=\"WIRELESS\") (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\")\n| bin _time span=15m\n| stats latest(clientCount) as cc by _time, clientType, scoreType\n| stats sum(cc) as cc by _time, scoreType\n| eval Good=if(scoreType==\"GOOD\",cc,null()), Fair=if(scoreType==\"FAIR\",cc,null()), Poor=if(scoreType==\"POOR\",cc,null())\n| stats sum(Good) as Good, sum(Fair) as Fair, sum(Poor) as Poor by _time",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_uxh_top_client_os": {
			"name": "IT Health - User Experience - ds_uxh_top_client_os",
			"options": {
				"extend": "ds_uxh_base_client_ref",
				"query": "| where isnotnull(osType) AND osType!=\"null\" AND osType!=\"\" AND osType!=\"Unknown\" AND osType!=\"unknown\" | stats dc(macAddress) as count by osType | sort -count | head 5 | rename osType as os"
			},
			"type": "ds.chain"
		},
		"ds_uxh_top_device_types": {
			"name": "IT Health - User Experience - ds_uxh_top_device_types",
			"options": {
				"extend": "ds_uxh_base_client_ref",
				"query": "| where isnotnull(deviceType) AND deviceType!=\"null\" AND deviceType!=\"\" AND deviceType!=\"Un-Classified Device\" | stats dc(macAddress) as Clients by deviceType | sort -Clients | head 5 | rename deviceType as \"Device Type\""
			},
			"type": "ds.chain"
		},
		"ds_uxh_wired_health": {
			"name": "IT Health - User Experience - ds_uxh_wired_health",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" scoreType=\"ALL\"\n| stats latest(scoreValue) as sv\n| eval score=if(sv>=0, sv, 0)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_uxh_wireless_health": {
			"name": "IT Health - User Experience - ds_uxh_wireless_health",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" scoreType=\"ALL\"\n| stats latest(scoreValue) as sv\n| eval score=if(sv>=0, sv, 0)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wow_health": {
			"name": "IT - Critical Systems - ds_wow_health",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:networkhealth\"\n| eval is_this_week=if(_time >= relative_time(now(), \"-7d@d\"), 1, 0)\n| stats avg(eval(if(is_this_week==1, healthScore, null()))) as this_week, avg(eval(if(is_this_week==0, healthScore, null()))) as last_week\n| eval score=round(this_week, 1), delta=round(this_week - last_week, 1)\n| table score delta",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
